 for(const p of pinDefs){const sleeve=annulus(g,.79,.59,3.8,[p.x,p.y,-5.9],metal,`${id} DIN pin ${p.n} hollow metal contact sleeve`);contacts.push(sleeve);for(const sign of[-1,1])mesh(g,new THREE.BoxGeometry(.12,.76,1.6),metal,[p.x+sign*.5,p.y,-5.9],`${id} DIN pin ${p.n} recessed spring`);stops.push(mesh(g,new THREE.CylinderGeometry(.79,.79,.22,24).rotateX(Math.PI/2),black,[p.x,p.y,-8.39],`${id} DIN pin ${p.n} recessed insertion stop`));mesh(g,new THREE.BoxGeometry(.5,.5,1.2),metal,[p.x,p.y,-10.8],`${id} DIN pin ${p.n} rear terminal`);}
