export function buildMidi(host){const parts=addCadParts(host,data,{shell:materials.plastic(0x646864,{roughness:.86}),lens:materials.plastic(0xcbd9cf,{roughness:.4,transparent:true,opacity:.8})});const electronics=board(host),dinIn=din(host,'midi-in-din','right'),dinOut=din(host,'midi-out-din','left'),jacks=spec.trs.map(s=>trs(host,s)),input=grove(host),control=mode(host);const guide=parts['MIDI native green power light guide'];guide.removeFromParent();const powerLed=host.add(new GreenPowerLed({id:'power-led',label:'LED1 · green power light guide',mesh:guide,color:spec.led.color,glowSize:2.8,radius:.1,meta:{role:'externally-driven-indicator',colorMode:'fixed-green',scope:'Default off. Independent external on/brightness appearance through own native light guide only; no automatic power, mode, MIDI, UART or audio linkage'}}));powerLed.glow.position.fromArray(spec.led.position);const ledPackage=mesh(host.body,new THREE.BoxGeometry(1.6,.8,.55),materials.plastic(0xd6d8c9,{roughness:.65}),[7.9,-17.4,-9.325],'MIDI LED1 fixed green physical package under native light guide');const fixing=screw(host.body,[0,-12,-12.46],'back',1.4);mesh(host.body,new THREE.CylinderGeometry(.65,.65,3,32).rotateX(Math.PI/2),materials.metal(0x939b90),[0,-12,-10.5],'MIDI concealed retaining screw shank');host.add(new Component({id:'sensor',label:'SAM2695 appearance anchor',position:[0,8,-8.3],meta:{role:'visual-anchor',scope:'Passive fixed visual anchor only; no note, synth, sound, MIDI routing, controller, serial, sensor-value, protocol or electrical commands'}}));host.midiAssembly={parts,electronics,dinIn,dinOut,jacks,input,controls:control,powerLed,guide,ledPackage,fixing};host.midiStickers=addStickers(host);}
